const assert = require('node:assert/strict');
const { ProfileService } = require('./.build/service');

// frozen stored profile: empty patch is still a no-op
{
  const frozen = Object.freeze({ displayName: 'x', tags: Object.freeze(['t']) });
  const svc = new ProfileService(frozen);
  assert.equal(svc.patch({}), frozen);
  assert.deepEqual(svc.patch({}), { displayName: 'x', tags: ['t'] });
}

// throwing getter / proxy are reported as invalid profile
{
  const hostile = {};
  Object.defineProperty(hostile, 'displayName', { get() { throw new TypeError('boom'); } });
  assert.throws(() => new ProfileService({ displayName: null, tags: [] }).patch(hostile), /invalid profile/);
}
{
  const proxy = new Proxy({}, { getPrototypeOf() { throw new TypeError('boom'); } });
  assert.throws(() => new ProfileService({ displayName: null, tags: [] }).patch(proxy), /invalid profile/);
}
{
  const proxy = new Proxy({}, { ownKeys() { throw new TypeError('boom'); } });
  assert.throws(() => new ProfileService({ displayName: null, tags: [] }).patch(proxy), /invalid profile/);
}

// non-enumerable extra own key is unknown
{
  const input = {};
  Object.defineProperty(input, 'secret', { value: 1, enumerable: false });
  assert.throws(() => new ProfileService({ displayName: null, tags: [] }).patch(input), /invalid profile/);
}

// null-prototype input with both fields
{
  const input = Object.create(null);
  input.displayName = ' n ';
  input.tags = [' x ', 'y'];
  const svc = new ProfileService({ displayName: 'old', tags: ['old'] });
  assert.deepEqual(svc.patch(input), { displayName: 'n', tags: ['x', 'y'] });
}

// sparse tag array is invalid, not coerced
{
  const sparse = ['a']; sparse[2] = 'b';
  assert.throws(() => new ProfileService({ displayName: null, tags: [] }).patch({ tags: sparse }), /invalid profile/);
}

// no input mutation, no tag array reuse, result carries trimmed values
{
  const input = { displayName: '  ok ', tags: [' one ', 'two'] };
  const snap = JSON.stringify(input);
  const svc = new ProfileService({ displayName: 'old', tags: ['old'] });
  const result = svc.patch(input);
  assert.equal(JSON.stringify(input), snap);
  assert.notEqual(result.tags, input.tags);
  assert.deepEqual(result, { displayName: 'ok', tags: ['one', 'two'] });
}

console.log('adversarial checks passed');
